    private void SelectSingleUnit(Vector2 worldPos)
    {
        // Clear previous selection
        foreach (var unit in selectedUnits)
            unit.IsSelected = false;
        selectedUnits.Clear();

        var u = OwnUnitAt(worldPos);
        if (u != null)
        {
